const inputData = $('Execute Workflow Trigger').first().json;
const cb = inputData.callback_data || '';

const text = inputData.text || '';
if (cb === 'cart_ver_historial' || text === '/estado') {
  let allPedidos = [];
  try { allPedidos = $('Read PEDIDOS').all().map(i => i.json); } catch(e) {}
  const misPedidos = allPedidos.filter(p => String(p.telegram_id) === String(inputData.telegram_id));
  if (misPedidos.length === 0) {
    return [{
      json: {
        mensaje: '📋 *Mis Pedidos*\n\nNo tienes pedidos recientes.',
        reply_markup: { inline_keyboard: [[{ text: '⬅️ Volver', callback_data: 'main_menu' }]] },
        session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: inputData.carrito_json || '[]', contexto_json: '{}' }
      }
    }];
  }
  const recientes = misPedidos.slice(-5).reverse();
  let texto = '📋 *Mis Pedidos*\n\n';
  recientes.forEach(function(p, idx) {
    const emoji = p.estado === 'ENTREGADO' ? '✅' : p.estado === 'PREPARACION' ? '🔥' : p.estado === 'EN_CAMINO' ? '🚴' : p.estado === 'RECIBIDO' ? '📦' : p.estado === 'CANCELADO' ? '❌' : '📦';
    texto += (idx+1) + '. ' + emoji + ' #' + p.id_pedido + '\n   Estado: ' + p.estado + ' | Total: $' + p.total_pago + '\n   Fecha: ' + p.fecha + '\n\n';
  });
  return [{
    json: {
      mensaje: texto,
      reply_markup: { inline_keyboard: [[{ text: '⬅️ Volver', callback_data: 'main_menu' }]] },
      session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: inputData.carrito_json || '[]', contexto_json: '{}' }
    }
  }];
}

let menuItems = [];
try { menuItems = $('Read Menu').all().map(i => i.json); } catch(e) {}

if (cb === 'cat_ver_todas' || cb === 'back_menu') {
  const categories = [...new Set(menuItems.filter(i => parseInt(i.stock) > 0).map(i => i.categoria))].filter(Boolean);
  const keyboard = categories.map(cat => ([{ text: '📁 ' + cat, callback_data: 'cat_' + cat }]));
  keyboard.push([{ text: '⬅️ Volver al Inicio', callback_data: 'main_menu' }]);
  return [{
    json: {
      mensaje: '🛒 *Categorías*\n\nSelecciona una categoría:',
      reply_markup: { inline_keyboard: keyboard },
      session_updates: { estado_fsm: 'SELECCION_CANTIDAD', carrito_json: inputData.carrito_json || '[]', contexto_json: inputData.contexto_json || '{}' }
    }
  }];
}

if (cb.startsWith('cat_') && cb !== 'cat_ver_todas') {
  const category = cb.replace('cat_', '');
  const items = menuItems.filter(i => i.categoria === category && parseInt(i.stock) > 0);
  const keyboard = items.map(item => ([{ text: '➕ ' + item.nombre + ' ($' + item.precio + ')', callback_data: 'add_' + item.id_producto }]));
  keyboard.push([{ text: '🛒 Ver Carrito', callback_data: 'view_cart' }]);
  keyboard.push([{ text: '⬅️ Categorías', callback_data: 'cat_ver_todas' }]);
  return [{
    json: {
      mensaje: '📁 *' + category + '*\n\nSelecciona un producto:',
      reply_markup: { inline_keyboard: keyboard },
      session_updates: { estado_fsm: 'SELECCION_CANTIDAD', carrito_json: inputData.carrito_json || '[]', contexto_json: JSON.stringify({ current_category: category }) }
    }
  }];
}

if (cb.startsWith('add_')) {
  const productId = cb.replace('add_', '');
  const product = menuItems.find(i => i.id_producto === productId);
  const stock = product ? parseInt(product.stock) : 5;
  const maxQty = Math.min(stock, 5);

  const qtyButtons = [];
  for (let i = 1; i <= maxQty; i++) {
    qtyButtons.push({ text: '' + i, callback_data: 'qty_' + productId + '_' + i });
  }

  return [{
    json: {
      mensaje: '🔢 *' + (product ? product.nombre : 'Producto') + '*\nPrecio: $' + (product ? product.precio : '0') + '\n\n¿Cuántas unidades deseas?',
      reply_markup: { inline_keyboard: [
        qtyButtons,
        [{ text: '⬅️ Volver', callback_data: inputData.contexto_json ? (function() { try { const c = JSON.parse(inputData.contexto_json); return c.current_category ? 'cat_' + c.current_category : 'cat_ver_todas'; } catch(e) { return 'cat_ver_todas'; } })() : 'cat_ver_todas' }]
      ]},
      session_updates: { estado_fsm: 'SELECCION_CANTIDAD', carrito_json: inputData.carrito_json || '[]', contexto_json: inputData.contexto_json || '{}' }
    }
  }];
}

if (cb.startsWith('qty_')) {
  const parts = cb.replace('qty_', '').split('_');
  const productId = parts.slice(0, -1).join('_');
  const qty = parseInt(parts[parts.length - 1]) || 1;
  const product = menuItems.find(i => i.id_producto === productId);

  let cart = [];
  try { cart = JSON.parse(inputData.carrito_json || '[]'); } catch(e) {}

  if (product) {
    const existing = cart.find(i => i.id === productId);
    if (existing) { existing.qty += qty; }
    else { cart.push({ id: productId, nombre: product.nombre, precio: parseFloat(product.precio), qty: qty }); }
  }

  let ctx = {};
  try { ctx = JSON.parse(inputData.contexto_json || '{}'); } catch(e) {}

  return [{
    json: {
      mensaje: '✅ ' + qty + 'x ' + (product ? product.nombre : 'Producto') + ' agregado al carrito.',
      reply_markup: { inline_keyboard: [
        [{ text: '⬅️ Seguir comprando', callback_data: ctx.current_category ? 'cat_' + ctx.current_category : 'cat_ver_todas' }],
        [{ text: '🛒 Ver Carrito', callback_data: 'view_cart' }]
      ]},
      session_updates: { estado_fsm: 'SELECCION_CANTIDAD', carrito_json: JSON.stringify(cart), contexto_json: inputData.contexto_json || '{}' }
    }
  }];
}

if (text === '/ayuda') {
  return [{
    json: {
      mensaje: '🤖 *Ayuda DeliveryBot*\n\nUsa los botones del menú para hacer tus pedidos. También puedes usar estos comandos:\n\n/start - Reiniciar el bot\n/estado - Ver tus pedidos recientes\n/cancelar - Vaciar tu carrito\n/ayuda - Mostrar este mensaje',
      reply_markup: { inline_keyboard: [[{ text: '⬅️ Menú Principal', callback_data: 'main_menu' }]] },
      session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: inputData.carrito_json || '[]', contexto_json: '{}' }
    }
  }];
}

if (cb === 'confirm_track') {
  return [{
    json: {
      mensaje: '📍 *Seguimiento*\n\nPor favor, ingresa tu número de orden (ej: ORD-1234):',
      reply_markup: { inline_keyboard: [[{ text: '⬅️ Volver', callback_data: 'main_menu' }]] },
      session_updates: { estado_fsm: 'TRACK_ORDER', carrito_json: inputData.carrito_json || '[]', contexto_json: '{}' }
    }
  }];
}

let baseMsg = '¡Bienvenido a DeliveryBot! 🍔\n\nPor favor, selecciona una opción:';
if (text === '/cancelar') {
  baseMsg = '✅ *Operación cancelada exitosamente y carrito vaciado.*\n\n' + baseMsg;
}

return [{
  json: {
    mensaje: baseMsg,
    reply_markup: { inline_keyboard: [
      [{ text: '🛒 Hacer Pedido', callback_data: 'cat_ver_todas' }],
      [{ text: '📋 Mis Pedidos', callback_data: 'cart_ver_historial' }, { text: '📍 Seguir Pedido', callback_data: 'confirm_track' }]
    ]},
    session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: '[]', contexto_json: '{}' }
  }
}];

const text = $('Execute Workflow Trigger').first().json.text || "";
let cancelOrderId = null;
if (text === "/cancelar") {
  try {
    let allPedidos = $('Read PEDIDOS').all().map(i => i.json);
    let myPending = allPedidos.filter(p => String(p.telegram_id) === String($('Execute Workflow Trigger').first().json.telegram_id) && p.estado === "RECIBIDO");
    if (myPending.length > 0) {
      cancelOrderId = myPending[myPending.length - 1].id_pedido;
    }
  } catch(e) {}
}
if (cancelOrderId) {
  return [{ json: { cancelOrderId: cancelOrderId, text: text } }];
}
return [{ json: { skip: true, text: text } }];
